import type { World } from './world.js';
import { WORLD_MIN_Y, WORLD_MAX_Y } from './world.js';
import type { BlockRegistry, Quad } from './blocks.js';

const FACE_SHADE = [0.5, 1.0, 0.8, 0.8, 0.6, 0.6];
